// Prompts are shown in a fixed, shuffled order and advance by one every day,
// counted continuously from a fixed epoch (not the calendar day-of-year,
// which would wrap on Jan 1 and only ever surface the first ~365 questions).
// A full lap through all 1000 takes about 2.7 years before any repeat.
const EPOCH = Date.UTC(2024, 0, 1);
const DAY_MS = 1000 * 60 * 60 * 24;

function indexForDate(date: Date): number {
  const daysSinceEpoch = Math.floor((Date.UTC(
    date.getUTCFullYear(),
    date.getUTCMonth(),
    date.getUTCDate(),
  ) - EPOCH) / DAY_MS);
  return ((daysSinceEpoch % REFLECTION_PROMPTS.length) + REFLECTION_PROMPTS.length) % REFLECTION_PROMPTS.length;
}

/**
 * Get today's daily prompt. Everyone sees the same question on a given day,
 * and it will not repeat until all 1000 have been shown.
 */
export function getTodayPrompt(): DailyPrompt {
  return REFLECTION_PROMPTS[indexForDate(new Date())];
}

/**
 * Get the prompt for a specific date, using the same non-repeating rotation.
 */
export function getPromptByDate(date: Date): DailyPrompt {
  return REFLECTION_PROMPTS[indexForDate(date)];
}

/**
 * Get a random prompt, independent of the daily rotation.
 */
export function getRandomPrompt(): DailyPrompt {
  return REFLECTION_PROMPTS[Math.floor(Math.random() * REFLECTION_PROMPTS.length)];
}

/**
 * Get the full list of prompt questions as plain strings, for callers (like
 * the daily tip notification) that just need text, not the full object.
 */
export function getAllPromptTexts(): string[] {
  return REFLECTION_PROMPTS.map((prompt) => prompt.question);
}

/**
 * Get prompt count
 */
export function getPromptCount(): number {
  return REFLECTION_PROMPTS.length;
}

export default REFLECTION_PROMPTS;
